-- ESIM-08 uses the existing order/run engine and wallet primitives.
ALTER TABLE esim_private.accounts ADD COLUMN recharge_enabled boolean NOT NULL DEFAULT false,
 ADD COLUMN recharge_contract_verified boolean NOT NULL DEFAULT false,
 ADD COLUMN wallet_boundary_verified boolean NOT NULL DEFAULT false;
ALTER TABLE public.esim_orders ADD COLUMN operation_kind text NOT NULL DEFAULT 'purchase'
 CHECK(operation_kind IN('purchase','fixed_recharge')),
 ADD COLUMN recharge_profile_id uuid REFERENCES public.user_esims(id),
 ADD COLUMN recharge_quote_id uuid REFERENCES esim_private.recharge_quotes(id);
ALTER TABLE public.esim_orders ADD COLUMN client_request_key uuid;
CREATE UNIQUE INDEX esim_purchase_request_key ON public.esim_orders(user_id,client_request_key) WHERE client_request_key IS NOT NULL;
ALTER TABLE public.esim_orders ADD CONSTRAINT esim_operation_shape CHECK(
 (operation_kind='purchase' AND recharge_profile_id IS NULL AND recharge_quote_id IS NULL) OR
 (operation_kind='fixed_recharge' AND recharge_profile_id IS NOT NULL AND recharge_quote_id IS NOT NULL AND quantity=1));
CREATE UNIQUE INDEX esim_one_quote_acceptance ON public.esim_orders(recharge_quote_id) WHERE recharge_quote_id IS NOT NULL;
CREATE UNIQUE INDEX esim_one_unresolved_profile_action ON public.esim_orders(recharge_profile_id)
 WHERE recharge_profile_id IS NOT NULL AND status IN('pending','processing');
CREATE INDEX esim_orders_recharge_owner ON public.esim_orders(user_id,recharge_profile_id,created_at);
ALTER TABLE esim_private.order_runs ADD COLUMN finance_kind text NOT NULL DEFAULT 'legacy_unverified'
 CHECK(finance_kind IN('reserved','legacy_debit','legacy_unverified')),
 ADD COLUMN payer_id uuid, ADD COLUMN hold_id uuid REFERENCES public.wallet_holds(id),
 ADD COLUMN debit_tx_id uuid REFERENCES public.wallet_transactions(id),
 ADD COLUMN settlement_tx_id uuid REFERENCES public.wallet_transactions(id),
 ADD COLUMN settlement_state text NOT NULL DEFAULT 'pending'
 CHECK(settlement_state IN('pending','capturing','captured','releasing','released','refunding','refunded','support_required')),
 ADD COLUMN receipt jsonb, ADD COLUMN receipt_hash text, ADD COLUMN receipt_at timestamptz;
ALTER TABLE esim_private.order_runs DROP CONSTRAINT order_runs_state_check;
ALTER TABLE esim_private.order_runs ADD CONSTRAINT order_runs_state_check CHECK(state IN('prepared','submitted','reconciling','support_required','completed','failed'));
CREATE UNIQUE INDEX esim_one_hold ON esim_private.order_runs(hold_id) WHERE hold_id IS NOT NULL;
CREATE UNIQUE INDEX esim_one_debit ON esim_private.order_runs(debit_tx_id) WHERE debit_tx_id IS NOT NULL;
CREATE TABLE esim_private.entitlements (
 order_id uuid PRIMARY KEY REFERENCES public.esim_orders(id), profile_id uuid NOT NULL REFERENCES public.user_esims(id),
 account_id uuid NOT NULL REFERENCES esim_private.accounts(id), supplier_topup_ref text NOT NULL,
 package_id text NOT NULL, allowance_bytes bigint NOT NULL CHECK(allowance_bytes>=0),
 duration_value integer NOT NULL,duration_unit text NOT NULL,retail_total numeric(12,2) NOT NULL CHECK(retail_total>0),
 currency text NOT NULL CHECK(currency='USD'),provider_expires_at timestamptz,expiry_confirmed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(account_id,supplier_topup_ref)
);
CREATE INDEX esim_entitlements_profile ON esim_private.entitlements(profile_id,created_at);
ALTER TABLE esim_private.entitlements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON esim_private.entitlements FROM PUBLIC,anon,authenticated;
GRANT SELECT ON esim_private.entitlements TO service_role;
-- Transaction-local capture provenance. Rows are inserted/deleted only by the
-- existing capture primitive; clients cannot forge a reservation exclusion.
CREATE TABLE esim_private.capture_context(txid bigint NOT NULL,hold_id uuid NOT NULL,wallet_id uuid NOT NULL,PRIMARY KEY(txid,hold_id));
CREATE INDEX esim_capture_context_wallet ON esim_private.capture_context(txid,wallet_id);
ALTER TABLE esim_private.capture_context ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON esim_private.capture_context FROM PUBLIC,anon,authenticated;
GRANT SELECT ON esim_private.capture_context TO service_role;
CREATE INDEX IF NOT EXISTS esim_active_holds_wallet ON public.wallet_holds(wallet_id) WHERE status='active';

-- Deliberate allowlist extensions; preserve all existing discriminator values.
ALTER TABLE public.wallet_holds ALTER COLUMN expires_at DROP NOT NULL;
ALTER TABLE public.wallet_holds ADD CONSTRAINT esim_hold_no_expiry CHECK(expires_at IS NOT NULL OR
 (order_type IN('esim_purchase','esim_recharge') AND order_reference_id LIKE 'esim_op:%'));
DO $$DECLARE expression text; BEGIN
 SELECT pg_get_expr(conbin,conrelid) INTO STRICT expression FROM pg_constraint
 WHERE conrelid='public.wallet_holds'::regclass AND conname='wallet_holds_order_type_check';
 ALTER TABLE public.wallet_holds DROP CONSTRAINT wallet_holds_order_type_check;
 EXECUTE format('ALTER TABLE public.wallet_holds ADD CONSTRAINT wallet_holds_order_type_check CHECK ((%s) OR order_type=''esim_recharge'')',expression);
 SELECT pg_get_expr(conbin,conrelid) INTO STRICT expression FROM pg_constraint
 WHERE conrelid='public.wallet_transactions'::regclass AND conname='wallet_transactions_type_check';
 ALTER TABLE public.wallet_transactions DROP CONSTRAINT wallet_transactions_type_check;
 EXECUTE format('ALTER TABLE public.wallet_transactions ADD CONSTRAINT wallet_transactions_type_check CHECK ((%s) OR type IN(''esim_recharge_debit'',''esim_recharge_refund''))',expression);
END $$;

CREATE FUNCTION esim_private.recharge_can_accept() RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT coalesce((SELECT a.recharge_enabled AND a.recharge_contract_verified AND a.wallet_boundary_verified
 AND p.discovery_enabled FROM esim_private.accounts a CROSS JOIN esim_private.recharge_policy p WHERE a.account_key='primary' AND p.singleton),false);
$$;
CREATE FUNCTION esim_private.require_live_owner(u uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT coalesce(is_suspended,false)) THEN
  RAISE EXCEPTION 'Account unavailable' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=u AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now())) THEN
  RAISE EXCEPTION 'Account unavailable' USING ERRCODE='42501'; END IF;
END $$;
CREATE FUNCTION esim_private.require_money_session(u uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
DECLARE session_id_value text;
BEGIN
 PERFORM esim_private.require_live_owner(u);
 session_id_value:=coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'session_id';
 IF coalesce(session_id_value,'')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
  RAISE EXCEPTION 'Active session required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=session_id_value::uuid AND user_id=u AND (not_after IS NULL OR not_after>now())) THEN
  RAISE EXCEPTION 'Active session required' USING ERRCODE='42501'; END IF;
END $$;

-- Namespace the new holds so historical holds and other workers are unaffected.
CREATE FUNCTION esim_private.reserve_order(p_order_id uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.esim_orders; r esim_private.order_runs; h uuid; w public.wallets;
BEGIN
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 IF auth.uid() IS DISTINCT FROM o.user_id AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;
 PERFORM esim_private.require_live_owner(o.user_id);
 SELECT * INTO STRICT w FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 IF w.currency IS DISTINCT FROM 'USD' THEN RAISE EXCEPTION 'Unsupported wallet currency'; END IF;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF r.hold_id IS NOT NULL THEN RETURN r.hold_id; END IF;
 IF r.state<>'prepared' OR r.submitted_at IS NOT NULL OR o.provider<>'esimaccess' THEN RAISE EXCEPTION 'Reservation intent unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE reference_id='esim_'||o.id::text AND type='esim_purchase_debit') THEN
  RAISE EXCEPTION 'Already-debited legacy order cannot be reserved'; END IF;
 UPDATE esim_private.order_runs SET finance_kind='reserved',payer_id=o.user_id WHERE order_id=o.id;
 h:=public.reserve_wallet_funds(o.user_id,o.total_amount_usd,
  CASE WHEN o.operation_kind='fixed_recharge' THEN 'esim_recharge' ELSE 'esim_purchase' END,'esim_op:'||o.id::text,'eSIM operation reservation',120);
 UPDATE esim_private.order_runs SET hold_id=h WHERE order_id=o.id;
 UPDATE public.wallet_holds SET expires_at=NULL WHERE id=h;
 RETURN h;
END $$;

CREATE FUNCTION esim_private.guard_operation_hold() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; o public.esim_orders; operation_id uuid;
BEGIN
 IF NEW.order_type NOT IN('esim_purchase','esim_recharge') OR NEW.order_reference_id NOT LIKE 'esim_op:%' THEN RETURN NEW; END IF;
 operation_id:=substr(NEW.order_reference_id,9)::uuid;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=operation_id;
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=operation_id;
 IF r.finance_kind<>'reserved' OR r.payer_id IS DISTINCT FROM NEW.user_id OR o.total_amount_usd IS DISTINCT FROM NEW.amount
  OR NEW.currency<>'USD' OR NEW.wallet_id IS DISTINCT FROM (SELECT id FROM public.wallets WHERE user_id=r.payer_id)
  OR NEW.order_type IS DISTINCT FROM (CASE WHEN o.operation_kind='fixed_recharge' THEN 'esim_recharge' ELSE 'esim_purchase' END) THEN
  RAISE EXCEPTION 'eSIM hold binding mismatch'; END IF;
 IF TG_OP='INSERT' THEN
  IF r.hold_id IS NOT NULL OR r.state<>'prepared' OR NEW.status<>'active' THEN RAISE EXCEPTION 'Invalid eSIM reservation'; END IF;
 ELSE
  IF (NEW.wallet_id,NEW.user_id,NEW.amount,NEW.order_type,NEW.order_reference_id,NEW.currency) IS DISTINCT FROM
     (OLD.wallet_id,OLD.user_id,OLD.amount,OLD.order_type,OLD.order_reference_id,OLD.currency) THEN RAISE EXCEPTION 'Immutable eSIM hold'; END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
   PERFORM esim_private.require_service();
   IF (NEW.status='captured' AND r.settlement_state='capturing' AND r.receipt IS NOT NULL) OR
      (NEW.status='released' AND r.settlement_state='releasing' AND r.state='failed' AND r.receipt IS NOT NULL) THEN NULL;
   ELSE RAISE EXCEPTION 'Unproven eSIM settlement'; END IF;
  END IF;
 END IF;
 -- New reservations have no timer-based release, even after a process restart.
 NEW.expires_at:=NULL;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_esim_operation_hold BEFORE INSERT OR UPDATE ON public.wallet_holds
FOR EACH ROW EXECUTE FUNCTION esim_private.guard_operation_hold();

CREATE FUNCTION esim_private.guard_reserved_wallet() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE floor_amount numeric;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.wallet_holds h JOIN esim_private.order_runs r ON r.hold_id=h.id
  WHERE h.wallet_id=OLD.id AND h.status='active') THEN RETURN NEW; END IF;
 IF NEW.balance IS NULL OR NEW.balance::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Invalid protected wallet balance'; END IF;
 IF NEW.balance>=OLD.balance THEN RETURN NEW; END IF;
 SELECT coalesce(sum(h.amount),0) INTO floor_amount FROM public.wallet_holds h
 WHERE h.wallet_id=OLD.id AND h.status='active' AND NOT EXISTS(
  SELECT 1 FROM esim_private.capture_context c WHERE c.txid=txid_current() AND c.hold_id=h.id AND c.wallet_id=OLD.id);
 IF NEW.balance<floor_amount THEN RAISE EXCEPTION 'Active reservations protect these funds'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_esim_reserved_wallet BEFORE UPDATE OF balance ON public.wallets
FOR EACH ROW EXECUTE FUNCTION esim_private.guard_reserved_wallet();

CREATE FUNCTION public.accept_esim_topup(p_quote_id uuid,p_acceptance_key uuid,p_device_id text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=auth.uid(); q esim_private.recharge_quotes; p public.user_esims; c esim_private.topup_cache;
 o public.esim_orders; total numeric; reason text; guard jsonb;
BEGIN
 PERFORM esim_private.require_money_session(u);
 SELECT * INTO q FROM esim_private.recharge_quotes WHERE id=p_quote_id AND owner_id=u AND payer_id=u AND acceptance_key=p_acceptance_key;
 IF NOT FOUND THEN RETURN '{"status":"QUOTE_UNAVAILABLE"}'::jsonb; END IF;
 -- Wallet -> profile -> quote/run/hold is the common financial lock order.
 PERFORM 1 FROM public.wallets WHERE user_id=u FOR UPDATE;
 SELECT * INTO p FROM public.user_esims WHERE id=q.profile_id AND user_id=u FOR UPDATE;
 IF NOT FOUND THEN RETURN '{"status":"PROFILE_UNAVAILABLE"}'::jsonb; END IF;
 SELECT * INTO o FROM public.esim_orders WHERE recharge_quote_id=q.id AND user_id=u;
 IF FOUND THEN RETURN jsonb_build_object('status','ADOPTED','order_id',o.id); END IF;
 IF NOT esim_private.recharge_can_accept() THEN RETURN '{"status":"RECHARGE_DISABLED"}'::jsonb; END IF;
 reason:=esim_private.topup_refusal(p);IF reason IS NOT NULL THEN RETURN jsonb_build_object('status',reason); END IF;
 SELECT * INTO c FROM esim_private.topup_cache WHERE profile_id=p.id AND owner_id=u AND account_id=q.account_id;
 IF q.expires_at<=now() OR c.expires_at<=now() OR c.status IS DISTINCT FROM 'ready' OR c.version IS DISTINCT FROM q.cache_version
  OR q.context IS DISTINCT FROM esim_private.topup_context(p) OR p.supplier_account_id IS DISTINCT FROM q.account_id THEN RETURN '{"status":"STALE_QUOTE"}'::jsonb; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.offers) x WHERE x->>'package_id'=q.package_id AND x->>'data_type'='1'
  AND (x->>'wholesale_usd')::numeric=q.wholesale_usd AND (x->>'allowance_bytes')::bigint>0) THEN RETURN '{"status":"INCOMPATIBLE_OFFER"}'::jsonb; END IF;
 total:=public.resolve_esim_offer_price(q.wholesale_usd,u);
 IF total IS DISTINCT FROM q.retail_total THEN RETURN '{"status":"PRICE_CHANGED"}'::jsonb; END IF;
 IF (esim_private.topup_balance(u,total)->>'balance_state')<>'sufficient' THEN RETURN '{"status":"BALANCE_UNAVAILABLE"}'::jsonb; END IF;
 guard:=public.guard_money_action('esim_purchase',total,p_device_id,NULL,u);
 IF coalesce((guard->>'blocked')::boolean,true) THEN RETURN '{"status":"DEVICE_BLOCKED"}'::jsonb; END IF;
 INSERT INTO public.esim_orders(user_id,offer_id,bundle_name,provider,quantity,wholesale_price_usd,retail_price_usd,markup_percent,
  total_amount_usd,status,operation_kind,recharge_profile_id,recharge_quote_id,catalogue_snapshot)
 VALUES(u,q.package_id,q.package_id,'esimaccess',1,q.wholesale_usd,total,round((total/q.wholesale_usd-1)*100,2),total,'pending',
  'fixed_recharge',p.id,q.id,jsonb_build_object('catalogue_details',q.retail_snapshot,'supplier_profile_ref',p.supplier_profile_ref,
  'iccid',p.iccid,'supplier_account_id',p.supplier_account_id,'quote_context',q.context)) RETURNING * INTO o;
 PERFORM esim_private.reserve_order(o.id);
 RETURN jsonb_build_object('status','ACCEPTED','order_id',o.id);
END $$;

CREATE FUNCTION esim_private.settle_order(p_order_id uuid,p_capture boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; o public.esim_orders; h public.wallet_holds; tx uuid; charged public.wallet_transactions;
 refunded numeric; ref text;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF r.settlement_state IN('captured','refunded','released') THEN
  IF (p_capture AND r.settlement_state<>'captured') OR (NOT p_capture AND r.settlement_state='captured') THEN RAISE EXCEPTION 'Settlement direction conflict'; END IF;
  RETURN r.settlement_tx_id;
 END IF;
 IF r.receipt IS NULL THEN RAISE EXCEPTION 'Receipt required'; END IF;
 IF r.finance_kind='reserved' THEN
  SELECT * INTO STRICT h FROM public.wallet_holds WHERE id=r.hold_id FOR UPDATE;
  IF h.user_id IS DISTINCT FROM r.payer_id OR h.amount IS DISTINCT FROM o.total_amount_usd OR h.status<>'active'
   OR h.order_reference_id IS DISTINCT FROM 'esim_op:'||o.id::text THEN RAISE EXCEPTION 'Reservation changed'; END IF;
  IF p_capture THEN
   IF r.receipt->>'outcome'<>'success' THEN RAISE EXCEPTION 'Confirmed service required'; END IF;
   UPDATE esim_private.order_runs SET settlement_state='capturing' WHERE order_id=o.id;
   tx:=public.capture_wallet_hold(h.id,CASE WHEN o.operation_kind='fixed_recharge' THEN 'esim_recharge_debit' ELSE 'esim_purchase_debit' END,
    'eSIM operation completed',jsonb_build_object('esim_order_id',o.id,'quote_id',o.recharge_quote_id,'action',o.operation_kind));
   UPDATE esim_private.order_runs SET settlement_state='captured',settlement_tx_id=tx WHERE order_id=o.id;
  ELSE
   IF r.state<>'failed' OR r.receipt->>'outcome'<>'failed' THEN RAISE EXCEPTION 'Definitive failure required'; END IF;
   UPDATE esim_private.order_runs SET settlement_state='releasing' WHERE order_id=o.id;
   PERFORM public.release_wallet_hold(h.id,'Verified eSIM failure or no submission');
   UPDATE esim_private.order_runs SET settlement_state='released' WHERE order_id=o.id;
  END IF;
 ELSIF r.finance_kind='legacy_debit' THEN
  SELECT * INTO STRICT charged FROM public.wallet_transactions WHERE id=r.debit_tx_id AND type='esim_purchase_debit'
   AND status='completed' AND reference_id='esim_'||o.id::text AND user_id=r.payer_id FOR UPDATE;
  IF charged.amount<=0 OR charged.amount::text IN('NaN','Infinity','-Infinity') OR charged.amount IS DISTINCT FROM (charged.balance_before-charged.balance_after) THEN RAISE EXCEPTION 'Unproven legacy charge'; END IF;
  IF charged.wallet_id IS DISTINCT FROM (SELECT id FROM public.wallets WHERE user_id=r.payer_id) THEN RAISE EXCEPTION 'Original wallet changed'; END IF;
  ref:='esim_refund_'||o.id::text;
  IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE status='completed'
   AND (reference_id=ref OR (metadata->>'esim_order_id'=o.id::text AND type IN('refund','esim_purchase_refund')))
   AND (user_id IS DISTINCT FROM r.payer_id OR wallet_id IS DISTINCT FROM charged.wallet_id OR type NOT IN('refund','esim_purchase_refund')
    OR amount<=0 OR balance_after-balance_before IS DISTINCT FROM amount)) THEN RAISE EXCEPTION 'Unproven prior refund'; END IF;
  SELECT coalesce(sum(amount),0) INTO refunded FROM public.wallet_transactions WHERE status='completed' AND
   (reference_id=ref OR (metadata->>'esim_order_id'=o.id::text AND type IN('refund','esim_purchase_refund')));
  IF p_capture THEN
   IF refunded<>0 THEN RAISE EXCEPTION 'Legacy delivery has prior refund; support required'; END IF;
   tx:=charged.id;
   UPDATE esim_private.order_runs SET settlement_state='captured',settlement_tx_id=tx WHERE order_id=o.id;
  ELSE
   IF r.state<>'failed' OR r.receipt->>'outcome'<>'failed' OR refunded>charged.amount THEN RAISE EXCEPTION 'Unproven legacy refund'; END IF;
   IF EXISTS(SELECT 1 FROM public.user_esims WHERE order_id=o.id) THEN RAISE EXCEPTION 'Partial issuance requires support'; END IF;
   IF refunded<charged.amount THEN
    UPDATE esim_private.order_runs SET settlement_state='refunding' WHERE order_id=o.id;
    tx:=public.credit_wallet_for_refund(r.payer_id,charged.amount-refunded,ref,'Verified legacy eSIM failure',NULL,'esim_purchase_refund');
   END IF;
   UPDATE esim_private.order_runs SET settlement_state='refunded',settlement_tx_id=coalesce(tx,settlement_tx_id) WHERE order_id=o.id;
  END IF;
 ELSE RAISE EXCEPTION 'Legacy financial proof required';
 END IF;
 RETURN tx;
END $$;

CREATE FUNCTION public.service_esim_fail_before_submit(p_order_id uuid,p_lease uuid,p_code text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; u uuid;
BEGIN
 PERFORM esim_private.require_service();
 SELECT user_id INTO STRICT u FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=u FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 IF r.state<>'prepared' OR r.submitted_at IS NOT NULL OR p_lease IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until<now()
  OR r.finance_kind<>'reserved' THEN RETURN false; END IF;
 IF p_code NOT IN('QUOTE_EXPIRED','SUPPLIER_DISABLED','PROFILE_CHANGED','PRICE_CHANGED','CREDENTIALS_UNAVAILABLE','COMPATIBILITY_CHANGED','SUBMISSION_DISABLED','JOURNAL_UNAVAILABLE') THEN RAISE EXCEPTION 'Invalid pre-submission refusal'; END IF;
 UPDATE esim_private.order_runs SET state='failed',receipt=jsonb_build_object('outcome','failed','source','before_submission','code',p_code),
  error_code=p_code,receipt_at=now(),next_check_at=NULL,lease=NULL,lease_until=NULL WHERE order_id=p_order_id;
 PERFORM esim_private.settle_order(p_order_id,false);
 UPDATE public.esim_orders SET status='failed',delivery_state='failed',updated_at=now() WHERE id=p_order_id;
 RETURN true;
END $$;

CREATE FUNCTION public.service_esim_record_topup_receipt(p_order_id uuid,p_submission_ref text,p_receipt jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.esim_orders; r esim_private.order_runs; p public.user_esims; digest_value text;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 SELECT * INTO STRICT p FROM public.user_esims WHERE id=o.recharge_profile_id FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF o.operation_kind<>'fixed_recharge' OR r.submitted_at IS NULL OR r.submission_ref IS DISTINCT FROM p_submission_ref
  OR p_receipt->>'transaction_id' IS DISTINCT FROM r.submission_ref OR p_receipt->>'iccid' IS DISTINCT FROM o.catalogue_snapshot->>'iccid'
  OR p_receipt->>'supplier_profile_ref' IS DISTINCT FROM o.catalogue_snapshot->>'supplier_profile_ref'
  OR p.user_id IS DISTINCT FROM o.user_id OR p.supplier_account_id IS DISTINCT FROM r.account_id
  OR p.iccid IS DISTINCT FROM p_receipt->>'iccid' OR p.supplier_profile_ref IS DISTINCT FROM p_receipt->>'supplier_profile_ref'
  OR p_receipt->>'package_id' IS DISTINCT FROM o.bundle_name OR p_receipt->>'outcome'<>'success'
  OR nullif(p_receipt->>'topup_ref','') IS NULL OR length(p_receipt->>'topup_ref')>100 OR octet_length(p_receipt::text)>4096
  OR coalesce(p_receipt->>'total_bytes','')!~'^[0-9]{1,16}$' OR coalesce(p_receipt->>'used_bytes','')!~'^[0-9]{1,16}$'
  OR (p_receipt->>'used_bytes')::bigint>(p_receipt->>'total_bytes')::bigint OR (p_receipt->>'expires_at')::timestamptz IS NULL
  OR NOT isfinite((p_receipt->>'expires_at')::timestamptz) THEN RAISE EXCEPTION 'Unproven recharge receipt'; END IF;
 digest_value:=encode(sha256(convert_to(p_receipt::text,'UTF8')),'hex');
 IF r.receipt IS NOT NULL THEN
  IF r.receipt_hash IS DISTINCT FROM digest_value THEN RAISE EXCEPTION 'Conflicting receipt'; END IF;RETURN true;
 END IF;
 IF r.state NOT IN('submitted','reconciling','support_required') THEN RAISE EXCEPTION 'Invalid receipt state'; END IF;
 UPDATE esim_private.order_runs SET receipt=p_receipt,receipt_hash=digest_value,receipt_at=now(),state='reconciling',next_check_at=now(),
  provider_order_ref=p_receipt->>'topup_ref',error_code=NULL WHERE order_id=o.id;
 RETURN true;
END $$;

CREATE FUNCTION public.service_esim_adopt_purchase_reference(p_order_id uuid,p_submission_ref text,p_provider_order_ref text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; o public.esim_orders;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 IF o.operation_kind<>'purchase' OR r.submission_ref IS DISTINCT FROM p_submission_ref OR r.submitted_at IS NULL
  OR nullif(p_provider_order_ref,'') IS NULL OR length(p_provider_order_ref)>100 THEN RAISE EXCEPTION 'Unproven purchase reference'; END IF;
 IF r.provider_order_ref IS NOT NULL AND r.provider_order_ref IS DISTINCT FROM p_provider_order_ref THEN RAISE EXCEPTION 'Conflicting purchase reference'; END IF;
 IF r.state='completed' THEN RETURN true; END IF;
 IF r.state NOT IN('submitted','reconciling','support_required') THEN RETURN false; END IF;
 UPDATE esim_private.order_runs SET provider_order_ref=p_provider_order_ref,state='reconciling',next_check_at=now(),
  lease=NULL,lease_until=NULL,error_code=NULL WHERE order_id=p_order_id;
 RETURN true;
END $$;

CREATE FUNCTION public.service_esim_settle_topup(p_order_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.esim_orders; r esim_private.order_runs; p public.user_esims; q esim_private.recharge_quotes; receipt_value jsonb;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 SELECT * INTO STRICT p FROM public.user_esims WHERE id=o.recharge_profile_id FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF r.state='completed' AND r.settlement_state='captured' THEN RETURN '{"completed":true}'::jsonb; END IF;
 receipt_value:=r.receipt;
 IF o.operation_kind<>'fixed_recharge' OR receipt_value IS NULL OR receipt_value->>'outcome'<>'success'
  OR p.user_id IS DISTINCT FROM o.user_id OR p.iccid IS DISTINCT FROM receipt_value->>'iccid'
  OR p.supplier_profile_ref IS DISTINCT FROM receipt_value->>'supplier_profile_ref' THEN RAISE EXCEPTION 'Settlement binding changed'; END IF;
 SELECT * INTO STRICT q FROM esim_private.recharge_quotes WHERE id=o.recharge_quote_id;
 PERFORM esim_private.settle_order(o.id,true);
 INSERT INTO esim_private.entitlements(order_id,profile_id,account_id,supplier_topup_ref,package_id,allowance_bytes,duration_value,duration_unit,retail_total,currency,provider_expires_at,expiry_confirmed)
 VALUES(o.id,p.id,r.account_id,receipt_value->>'topup_ref',o.bundle_name,(q.retail_snapshot->>'allowance_bytes')::bigint,
 q.duration_value,q.duration_unit,o.total_amount_usd,'USD',(receipt_value->>'expires_at')::timestamptz,p.bundle_state IN('active','depleted'));
 UPDATE public.user_esims SET data_total_bytes=(receipt_value->>'total_bytes')::bigint,data_used_bytes=(receipt_value->>'used_bytes')::bigint,
  data_remaining_bytes=(receipt_value->>'total_bytes')::bigint-(receipt_value->>'used_bytes')::bigint,
  data_total_mb=floor((receipt_value->>'total_bytes')::numeric/1048576),
  data_remaining_mb=floor(((receipt_value->>'total_bytes')::numeric-(receipt_value->>'used_bytes')::numeric)/1048576),
  confirmed_expires_at=CASE WHEN bundle_state IN('active','depleted') THEN (receipt_value->>'expires_at')::timestamptz ELSE confirmed_expires_at END,
  expires_at=CASE WHEN bundle_state IN('active','depleted') THEN (receipt_value->>'expires_at')::timestamptz ELSE expires_at END,
  bundle_state=CASE WHEN bundle_state='depleted' THEN 'active' ELSE bundle_state END,last_observation_at=clock_timestamp(),
  last_usage_check=clock_timestamp(),usage_observed_at=NULL,usage_error_code=NULL WHERE id=p.id;
 PERFORM esim_private.open_alert_cycle(p.id,'recharge:'||o.id::text);
 DELETE FROM esim_private.topup_cache WHERE profile_id=p.id;
 UPDATE esim_private.profile_work SET next_check_at=now() WHERE profile_id=p.id;
 UPDATE esim_private.order_runs SET state='completed',lease=NULL,lease_until=NULL,next_check_at=NULL,error_code=NULL,updated_at=now() WHERE order_id=o.id;
 UPDATE public.esim_orders SET status='completed',delivery_state='completed',provider_order_ref=receipt_value->>'topup_ref',updated_at=now() WHERE id=o.id;
 RETURN '{"completed":true}'::jsonb;
END $$;

CREATE FUNCTION public.service_esim_record_rejection(p_order_id uuid,p_lease uuid,p_submission_ref text,p_code text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; u uuid;
BEGIN
 PERFORM esim_private.require_service();
 SELECT user_id INTO STRICT u FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=u FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 IF r.state='failed' AND r.settlement_state IN('released','refunded') THEN RETURN true; END IF;
 IF p_lease IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until<now() OR r.state<>'submitted'
  OR r.submission_ref IS DISTINCT FROM p_submission_ref OR p_code NOT IN('200005','200006','200007','200008','310241','310243') THEN RETURN false; END IF;
 UPDATE esim_private.order_runs SET state='failed',receipt=jsonb_build_object('outcome','failed','source','inline_validation_rejection',
  'transaction_id',p_submission_ref,'code',p_code),receipt_at=now(),next_check_at=NULL,error_code='PROVIDER_REJECTED' WHERE order_id=p_order_id;
 PERFORM esim_private.settle_order(p_order_id,false);
 UPDATE esim_private.order_runs SET lease=NULL,lease_until=NULL WHERE order_id=p_order_id;
 UPDATE public.esim_orders SET status='failed',delivery_state='failed',updated_at=now() WHERE id=p_order_id;
 RETURN true;
END $$;

CREATE FUNCTION public.get_esim_operation_history(p_profile_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=auth.uid(); result jsonb;
BEGIN
 PERFORM esim_private.require_live_owner(u);
 IF p_profile_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_esims WHERE id=p_profile_id AND user_id=u) THEN RETURN '[]'::jsonb; END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY created_at DESC),'[]') INTO result FROM(
  SELECT o.created_at,jsonb_build_object('id',o.id,'profile_id',o.recharge_profile_id,'kind',o.operation_kind,'package_id',o.bundle_name,
   'retail_total',o.total_amount_usd,'currency','USD','status',o.status,'delivery_state',o.delivery_state,'created_at',o.created_at,
   'financial_state',coalesce(r.settlement_state,'support_required'),'funds_reserved',r.finance_kind='reserved' AND r.settlement_state='pending',
   'confirmed_expiry',CASE WHEN e.expiry_confirmed THEN e.provider_expires_at END,'duration_value',e.duration_value,'duration_unit',e.duration_unit,
   'support_required',o.delivery_state='support_required') value
  FROM public.esim_orders o LEFT JOIN esim_private.order_runs r ON r.order_id=o.id
  LEFT JOIN esim_private.entitlements e ON e.order_id=o.id WHERE o.user_id=u
   AND (p_profile_id IS NULL OR o.recharge_profile_id=p_profile_id OR o.id=(SELECT order_id FROM public.user_esims WHERE id=p_profile_id AND user_id=u))
  ORDER BY o.created_at DESC LIMIT 50) rows;
 RETURN result;
END $$;

CREATE FUNCTION public.admin_esim_operation_timeline(p_order_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.assert_admin();
 SELECT jsonb_build_object('order_id',o.id,'kind',o.operation_kind,'status',o.status,'delivery_state',o.delivery_state,
 'finance_kind',r.finance_kind,'settlement_state',r.settlement_state,'submitted_at',r.submitted_at,'receipt_at',r.receipt_at,
 'error_code',r.error_code,'attempts',r.attempts,'next_check_at',r.next_check_at,'has_hold',r.hold_id IS NOT NULL,
 'has_original_debit',r.debit_tx_id IS NOT NULL,'has_settlement',r.settlement_tx_id IS NOT NULL,'receipt_hash',r.receipt_hash,
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('received_at',received_at,'status',status,'kind',kind)),'[]') FROM esim_private.events
  WHERE account_id=r.account_id AND (submission_ref=r.submission_ref OR order_ref=r.provider_order_ref))) INTO result
 FROM public.esim_orders o JOIN esim_private.order_runs r ON r.order_id=o.id WHERE o.id=p_order_id;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.capture_wallet_hold(p_hold_id uuid, p_txn_type text DEFAULT 'topup_debit'::text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hold RECORD;
  v_wallet RECORD;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_alloc RECORD;
BEGIN
  -- Use the common wallet-before-hold order.
  PERFORM 1 FROM public.wallets WHERE id=(SELECT wallet_id FROM public.wallet_holds WHERE id=p_hold_id) FOR UPDATE;
  -- Lock hold
  SELECT * INTO v_hold
  FROM public.wallet_holds
  WHERE id = p_hold_id
  FOR UPDATE;

  IF v_hold.id IS NULL THEN
    RAISE EXCEPTION 'Hold not found: %', p_hold_id;
  END IF;

  IF v_hold.status = 'captured' THEN
    -- Idempotent retry: return existing transaction if recorded in metadata
    SELECT id INTO v_txn_id
    FROM public.wallet_transactions
    WHERE reference_id = 'hold_' || p_hold_id::text;
    IF v_txn_id IS NOT NULL THEN
      RETURN v_txn_id;
    END IF;
  END IF;

  IF v_hold.status != 'active' THEN
    RAISE EXCEPTION 'Cannot capture hold in status: %', v_hold.status;
  END IF;

  -- Lock wallet
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE id = v_hold.wallet_id
  FOR UPDATE;

  IF v_wallet.balance < v_hold.amount THEN
    RAISE EXCEPTION 'Invariant violation: wallet balance % is less than hold amount %', v_wallet.balance, v_hold.amount;
  END IF;

  v_balance_after := v_wallet.balance - v_hold.amount;

  INSERT INTO esim_private.capture_context(txid,hold_id,wallet_id)
  SELECT txid_current(),p_hold_id,v_wallet.id WHERE EXISTS(SELECT 1 FROM public.wallet_holds h JOIN esim_private.order_runs r ON r.hold_id=h.id WHERE h.wallet_id=v_wallet.id AND h.status='active')
  ON CONFLICT DO NOTHING;
  -- Update wallet balance
  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + v_hold.amount,
      updated_at = now()
  WHERE id = v_wallet.id;

  -- Update allocated lots (consume remaining_amount)
  FOR v_alloc IN
    SELECT * FROM public.wallet_hold_allocations
    WHERE hold_id = p_hold_id
  LOOP
    UPDATE public.wallet_funding_lots
    SET remaining_amount = remaining_amount - v_alloc.amount,
        status = CASE WHEN remaining_amount - v_alloc.amount = 0 THEN 'fully_consumed' ELSE status END,
        updated_at = now()
    WHERE id = v_alloc.lot_id;
  END LOOP;

  -- Mark hold captured
  UPDATE public.wallet_holds
  SET status = 'captured',
      captured_at = now(),
      updated_at = now()
  WHERE id = p_hold_id;

  -- Record ledger transaction
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata, created_at
  ) VALUES (
    v_wallet.id, v_hold.user_id, p_txn_type, v_hold.amount, v_wallet.balance, v_balance_after,
    COALESCE(p_description, 'Purchase completed'),
    'hold_' || p_hold_id::text,
    'completed',
    jsonb_build_object('hold_id', p_hold_id, 'order_type', v_hold.order_type, 'order_reference_id', v_hold.order_reference_id) || COALESCE(p_metadata, '{}'::jsonb),
    now()
  ) RETURNING id INTO v_txn_id;

  DELETE FROM esim_private.capture_context WHERE txid=txid_current() AND hold_id=p_hold_id;
  RETURN v_txn_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.service_esim_claim_order(p_account_key text DEFAULT 'primary'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a esim_private.accounts%ROWTYPE; r esim_private.order_runs%ROWTYPE; result jsonb;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT a FROM esim_private.accounts WHERE account_key=p_account_key;
 SELECT run.* INTO r FROM esim_private.order_runs run JOIN public.esim_orders o ON o.id=run.order_id
 WHERE run.account_id=a.id AND run.state<>'completed' AND o.user_id IS NOT NULL
   AND o.status IN('pending','processing') AND run.next_check_at<=now()
   AND (run.lease_until IS NULL OR run.lease_until<now())
   AND (run.state<>'prepared' OR run.finance_kind='reserved')
 ORDER BY run.next_check_at FOR UPDATE OF run SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE esim_private.order_runs SET lease=gen_random_uuid(),lease_until=now()+interval '2 minutes',attempts=attempts+1
 WHERE order_id=r.order_id RETURNING * INTO r;
 UPDATE public.esim_orders SET status='processing',delivery_state=r.state,updated_at=now() WHERE id=r.order_id;
 SELECT jsonb_build_object('order_id',o.id,'user_id',o.user_id,'bundle_name',o.bundle_name,'quantity',o.quantity,
  'wholesale_price_usd',o.wholesale_price_usd,'catalogue_snapshot',o.catalogue_snapshot,'lease',r.lease,
  'state',r.state,'submission_ref',r.submission_ref,'provider_order_ref',r.provider_order_ref,'hinted_order_ref',r.hinted_order_ref,'operation_kind',o.operation_kind,'has_receipt',r.receipt IS NOT NULL,
 'supplier_profile_ref',o.catalogue_snapshot->>'supplier_profile_ref','iccid',o.catalogue_snapshot->>'iccid')
 INTO result FROM public.esim_orders o WHERE o.id=r.order_id;
 RETURN result;
END $function$;

CREATE OR REPLACE FUNCTION public.quote_esim_topup(p_profile_id uuid, p_package_id text, p_offer_version uuid, p_expected_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); p public.user_esims%ROWTYPE; c esim_private.topup_cache%ROWTYPE; q esim_private.recharge_quotes%ROWTYPE;
 o jsonb; retail jsonb; total numeric; reason text;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.user_esims WHERE id=p_profile_id AND user_id=u FOR UPDATE;
 IF NOT FOUND THEN RETURN '{"status":"PROFILE_UNAVAILABLE"}'::jsonb; END IF;
 IF NOT (SELECT discovery_enabled FROM esim_private.recharge_policy WHERE singleton) THEN RETURN '{"status":"DISCOVERY_DISABLED"}'::jsonb; END IF;
 reason:=esim_private.topup_refusal(p); IF reason IS NOT NULL THEN RETURN jsonb_build_object('status',reason); END IF;
 SELECT * INTO c FROM esim_private.topup_cache WHERE profile_id=p.id AND owner_id=u AND account_id=p.supplier_account_id;
 IF NOT FOUND OR c.status<>'ready' OR c.expires_at<=now() OR c.context IS DISTINCT FROM esim_private.topup_context(p)
  OR p_offer_version IS NULL OR c.version IS DISTINCT FROM p_offer_version THEN RETURN '{"status":"STALE_OFFERS"}'::jsonb; END IF;
 SELECT value INTO o FROM jsonb_array_elements(c.offers) WHERE value->>'package_id'=p_package_id;
 IF NOT FOUND THEN RETURN '{"status":"INCOMPATIBLE_OFFER"}'::jsonb; END IF;
 IF o->>'data_type'<>'1' THEN RETURN '{"status":"DURATION_QUOTE_UNAVAILABLE"}'::jsonb; END IF;
 retail:=esim_private.topup_retail(o,u); total:=(retail->>'retail_total')::numeric;
 IF total IS NULL OR total<=0 OR total::text IN('NaN','Infinity','-Infinity') THEN RETURN '{"status":"PRICE_UNAVAILABLE"}'::jsonb; END IF;
 IF p_expected_total IS NULL OR total IS DISTINCT FROM p_expected_total THEN RETURN '{"status":"PRICE_CHANGED"}'::jsonb; END IF;
 SELECT * INTO q FROM esim_private.recharge_quotes WHERE owner_id=u AND profile_id=p.id AND cache_version=c.version
  AND package_id=p_package_id AND retail_total=total AND expires_at>now() AND NOT EXISTS(SELECT 1 FROM public.esim_orders accepted WHERE accepted.recharge_quote_id=recharge_quotes.id) ORDER BY created_at DESC LIMIT 1;
 IF NOT FOUND THEN
  IF (SELECT count(*) FROM esim_private.recharge_quotes WHERE owner_id=u AND created_at>now()-interval '1 minute')>=20 THEN RETURN '{"status":"RATE_LIMITED"}'::jsonb; END IF;
  INSERT INTO esim_private.recharge_quotes(owner_id,payer_id,profile_id,account_id,provider,action,package_id,cache_version,context,
   wholesale_usd,retail_total,currency,duration_value,duration_unit,retail_snapshot,expires_at)
  VALUES(u,u,p.id,p.supplier_account_id,p.provider,'fixed_bundle_recharge',p_package_id,c.version,c.context,
   (o->>'wholesale_usd')::numeric,total,'USD',(o->>'duration_value')::integer,o->>'duration_unit',retail,least(c.expires_at,now()+interval '2 minutes')) RETURNING * INTO q;
 END IF;
 RETURN jsonb_build_object('status','QUOTED','quote_id',q.id,'acceptance_key',q.acceptance_key,'owner_id',u,'payer_id',u,
  'profile_id',p.id,'action',q.action,'offer',q.retail_snapshot,'expires_at',q.expires_at,'acceptance_enabled',esim_private.recharge_can_accept())
  ||esim_private.topup_balance(u,total);
END $function$;

CREATE OR REPLACE FUNCTION public.check_esim_topup_quote(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); p public.user_esims%ROWTYPE; q esim_private.recharge_quotes%ROWTYPE; c esim_private.topup_cache%ROWTYPE;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO q FROM esim_private.recharge_quotes WHERE id=p_quote_id AND owner_id=u AND payer_id=u;
 IF NOT FOUND THEN RETURN '{"status":"QUOTE_UNAVAILABLE"}'::jsonb; END IF;
 SELECT * INTO p FROM public.user_esims WHERE id=q.profile_id AND user_id=u;
 SELECT * INTO c FROM esim_private.topup_cache WHERE profile_id=q.profile_id;
 IF p.id IS NULL OR q.expires_at<=now() OR c.status IS DISTINCT FROM 'ready' OR c.expires_at<=now()
  OR c.version IS DISTINCT FROM q.cache_version OR q.context IS DISTINCT FROM esim_private.topup_context(p)
  OR q.account_id IS DISTINCT FROM p.supplier_account_id OR esim_private.topup_refusal(p) IS NOT NULL
  OR NOT (SELECT discovery_enabled FROM esim_private.recharge_policy WHERE singleton)
  OR public.resolve_esim_offer_price(q.wholesale_usd,u) IS DISTINCT FROM q.retail_total THEN RETURN '{"status":"STALE_QUOTE","acceptance_enabled":false}'::jsonb; END IF;
 RETURN jsonb_build_object('status','QUOTED','quote_id',q.id,'acceptance_key',q.acceptance_key,'owner_id',u,'payer_id',u,
 'profile_id',p.id,'action',q.action,'offer',q.retail_snapshot,'expires_at',q.expires_at,'acceptance_enabled',esim_private.recharge_can_accept())||esim_private.topup_balance(u,q.retail_total);
END $function$;

CREATE OR REPLACE FUNCTION esim_private.topup_refusal_base(p user_esims)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
BEGIN
 IF p.provider<>'esimaccess' OR p.supplier_account_id IS NULL OR nullif(p.supplier_profile_ref,'') IS NULL
  OR coalesce(p.iccid,'')!~'^[0-9]{15,22}$' THEN RETURN 'UNSUPPORTED_PROFILE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.esim_suppliers WHERE code=p.provider AND is_active)
  OR NOT EXISTS(SELECT 1 FROM esim_private.accounts WHERE id=p.supplier_account_id AND provider=p.provider AND account_key='primary') THEN RETURN 'SUPPLIER_DISABLED'; END IF;
 IF p.profile_state IN('expired','cancelled','revoked') OR p.bundle_state IN('expired','cancelled')
  OR p.confirmed_expires_at<=now() OR (p.bundle_state='not_started' AND p.activation_deadline_at<=now()) THEN RETURN 'PROFILE_EXPIRED'; END IF;
 IF p.profile_state NOT IN('issued','active') OR p.bundle_state NOT IN('not_started','active','depleted')
  OR p.installation_state NOT IN('released','downloaded','installed','enabled') THEN RETURN 'PROFILE_UNAVAILABLE'; END IF;
 IF p.last_observation_at IS NULL OR p.last_observation_at<now()-interval '15 minutes' OR p.usage_error_code IS NOT NULL
  OR (p.bundle_state IN('active','depleted') AND p.confirmed_expires_at IS NULL) THEN RETURN 'PROFILE_REFRESH_REQUIRED'; END IF;
 IF p.plan_details->>'topup_support'='unsupported' THEN RETURN 'TOPUP_UNSUPPORTED'; END IF;
 IF coalesce(p.plan_details->>'topup_support','unknown') NOT IN('supported','daily_extension') THEN RETURN 'CAPABILITY_UNVERIFIED'; END IF;
 IF EXISTS(SELECT 1 FROM esim_private.order_runs WHERE order_id=p.order_id AND state<>'completed')
  OR EXISTS(SELECT 1 FROM public.esim_orders WHERE id=p.order_id AND status IN('pending','processing')) THEN RETURN 'UNRESOLVED_OPERATION'; END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION esim_private.topup_refusal(p public.user_esims) RETURNS text
 LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE reason text; BEGIN
 reason:=esim_private.topup_refusal_base(p); IF reason IS NOT NULL THEN RETURN reason; END IF;
 IF EXISTS(SELECT 1 FROM public.esim_orders WHERE recharge_profile_id=p.id AND status IN('pending','processing')) THEN RETURN 'UNRESOLVED_OPERATION'; END IF;
 RETURN NULL; END $$;

CREATE OR REPLACE FUNCTION public.gate_esim_order_submission() RETURNS trigger
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a esim_private.accounts; BEGIN
 SELECT * INTO STRICT a FROM esim_private.accounts WHERE account_key='primary';
 IF NEW.provider<>'esimaccess' OR (NEW.operation_kind='purchase' AND (NOT a.new_sales_enabled OR NOT a.wallet_boundary_verified))
  OR (NEW.operation_kind='fixed_recharge' AND NOT esim_private.recharge_can_accept()) THEN
  RAISE EXCEPTION 'eSIM purchases are temporarily unavailable while delivery safeguards are verified'; END IF;
 NEW.delivery_state:='queued';RETURN NEW; END $$;

CREATE OR REPLACE FUNCTION public.service_esim_mark_submitted(p_order_id uuid,p_lease uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r esim_private.order_runs; o public.esim_orders; p public.user_esims; q esim_private.recharge_quotes; reason text; reject_code text; available numeric;
BEGIN
 PERFORM esim_private.require_service();SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 IF o.recharge_profile_id IS NOT NULL THEN SELECT * INTO STRICT p FROM public.user_esims WHERE id=o.recharge_profile_id FOR UPDATE; END IF;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF p_lease IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until IS NULL OR r.lease_until<now() OR r.state<>'prepared' OR r.submitted_at IS NOT NULL THEN RETURN false; END IF;
 IF r.finance_kind<>'reserved' OR r.hold_id IS NULL OR r.payer_id IS DISTINCT FROM o.user_id THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.esim_suppliers WHERE code=o.provider AND is_active) THEN reject_code:='SUPPLIER_DISABLED'; END IF;
 IF o.operation_kind='fixed_recharge' THEN
  IF NOT esim_private.recharge_can_accept() THEN reject_code:='SUBMISSION_DISABLED'; END IF;
  SELECT * INTO STRICT q FROM esim_private.recharge_quotes WHERE id=o.recharge_quote_id;
  IF q.expires_at<=now() THEN reject_code:='QUOTE_EXPIRED'; END IF;
  IF q.context IS DISTINCT FROM esim_private.topup_context(p) OR p.user_id IS DISTINCT FROM o.user_id
   OR p.supplier_account_id IS DISTINCT FROM r.account_id OR esim_private.topup_refusal_base(p) IS NOT NULL THEN reject_code:='PROFILE_CHANGED'; END IF;
  IF EXISTS(SELECT 1 FROM public.esim_orders WHERE recharge_profile_id=p.id AND id<>o.id AND status IN('pending','processing')) THEN reject_code:='PROFILE_CHANGED'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM esim_private.accounts WHERE id=r.account_id AND new_sales_enabled AND wallet_boundary_verified) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.esim_offers_cache WHERE provider=o.provider AND bundle_name=o.bundle_name AND is_active
   AND wholesale_price_usd=o.wholesale_price_usd) THEN reject_code:='PRICE_CHANGED'; END IF;
 END IF;
 IF public.resolve_esim_offer_price(o.wholesale_price_usd,o.user_id) IS DISTINCT FROM o.retail_price_usd THEN reject_code:='PRICE_CHANGED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=o.user_id AND NOT coalesce(is_suspended,false)) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.wallet_holds WHERE id=r.hold_id AND status='active' AND user_id=r.payer_id AND amount=o.total_amount_usd AND expires_at IS NULL) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 SELECT w.balance-coalesce((SELECT sum(amount) FROM public.wallet_holds WHERE wallet_id=w.id AND status='active'),0) INTO available FROM public.wallets w WHERE user_id=r.payer_id AND currency='USD';
 IF available IS NULL OR available<0 OR available::text IN('NaN','Infinity','-Infinity') THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF reject_code IS NOT NULL THEN PERFORM public.service_esim_fail_before_submit(o.id,p_lease,reject_code);RETURN false; END IF;
 UPDATE esim_private.order_runs SET state='submitted',submitted_at=now(),updated_at=now() WHERE order_id=o.id;
 UPDATE public.esim_orders SET delivery_state='submitted' WHERE id=o.id;RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.request_esim_purchase_v2(p_offer_id text,p_quantity integer,p_device_id text,p_request_key uuid,p_reviewed_total numeric,p_expected_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_offer RECORD;
  v_supplier_markup numeric;
  v_markup_percent numeric := 30.0;
  v_retail_price numeric(10,2);
  v_total_cost numeric(10,2);
  v_wallet_balance numeric(10,2);
  v_order_id uuid;
  v_txn_ref text;
  v_guard jsonb;
  existing public.esim_orders;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  END IF;

  IF p_expected_user IS DISTINCT FROM v_user_id THEN RETURN jsonb_build_object('success',false,'code','ACCOUNT_CHANGED'); END IF;
  PERFORM esim_private.require_money_session(v_user_id);
  IF p_request_key IS NULL OR p_reviewed_total IS NULL OR p_reviewed_total<=0 OR p_reviewed_total::text IN('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('success',false,'code','INVALID_REVIEWED_INTENT'); END IF;
  PERFORM 1 FROM public.wallets WHERE user_id=v_user_id FOR UPDATE;
  SELECT * INTO existing FROM public.esim_orders WHERE user_id=v_user_id AND client_request_key=p_request_key;
  IF FOUND THEN
    IF existing.offer_id IS DISTINCT FROM p_offer_id OR existing.quantity IS DISTINCT FROM p_quantity OR existing.total_amount_usd IS DISTINCT FROM p_reviewed_total THEN
      RETURN jsonb_build_object('success',false,'code','INTENT_CONFLICT'); END IF;
    RETURN jsonb_build_object('success',true,'order_id',existing.id,'status',existing.status,'adopted',true);
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = v_user_id AND is_suspended = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Account is suspended. Purchases are disabled.');
  END IF;

  PERFORM public.enforce_rate_limit('esim_purchase', v_user_id::text);

  IF p_quantity IS NULL OR p_quantity < 1 OR p_quantity > 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity must be between 1 and 3');
  END IF;

  SELECT c.* INTO v_offer
  FROM public.esim_offers_cache c
  JOIN public.esim_suppliers s ON s.code = c.provider AND s.is_active = true
  WHERE (c.bundle_name = p_offer_id OR (c.provider || '_' || c.bundle_name = p_offer_id))
    AND c.is_active = true
  ORDER BY c.updated_at DESC
  LIMIT 1;

  IF v_offer IS NULL OR v_offer.bundle_name IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'eSIM offer not found or inactive');
  END IF;

  -- Use canonical tier-based pricing via resolve_esim_offer_price
  v_retail_price := public.resolve_esim_offer_price(v_offer.wholesale_price_usd, v_user_id);
  IF v_retail_price IS NULL OR v_retail_price <= 0 THEN
    SELECT markup_percent_override INTO v_supplier_markup
    FROM public.esim_suppliers
    WHERE code = v_offer.provider;

    IF v_supplier_markup IS NOT NULL THEN
      v_markup_percent := v_supplier_markup;
    ELSE
      BEGIN
        SELECT config_value::numeric INTO v_markup_percent
        FROM public.system_configs WHERE config_key = 'ESIM_MARKUP_PERCENT';
      EXCEPTION WHEN OTHERS THEN v_markup_percent := 30.0; END;
    END IF;
    IF v_markup_percent IS NULL THEN v_markup_percent := 30.0; END IF;

    v_retail_price := round(v_offer.wholesale_price_usd * (1.0 + (v_markup_percent / 100.0)), 2);
  ELSE
    v_markup_percent := round(((v_retail_price - v_offer.wholesale_price_usd) / NULLIF(v_offer.wholesale_price_usd, 0)) * 100.0, 2);
  END IF;

  v_total_cost := v_retail_price * p_quantity;
  IF v_total_cost IS DISTINCT FROM p_reviewed_total THEN RETURN jsonb_build_object('success',false,'code','PRICE_CHANGED'); END IF;

  SELECT (public.get_wallet_summary(v_user_id)->>'available_balance')::numeric INTO v_wallet_balance;

  IF v_wallet_balance < v_total_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INSUFFICIENT_FUNDS',
      'error', 'Insufficient wallet balance. Required: $' || v_total_cost::text || ', Available: $' || v_wallet_balance::text
    );
  END IF;

  v_guard := public.guard_money_action('esim_purchase', v_total_cost, p_device_id, NULL, v_user_id);
  IF (v_guard ->> 'blocked')::boolean THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'DEVICE_BLOCKED',
      'reason', v_guard ->> 'reason',
      'error', 'This purchase was stopped by a security check on this device. Contact support if this is a mistake.'
    );
  END IF;

  INSERT INTO public.esim_orders (
    user_id, offer_id, bundle_name, provider, quantity, wholesale_price_usd, retail_price_usd, markup_percent, total_amount_usd, status, client_request_key
  ) VALUES (
    v_user_id, p_offer_id, v_offer.bundle_name, v_offer.provider, p_quantity, v_offer.wholesale_price_usd, v_retail_price, v_markup_percent, v_total_cost, 'pending', p_request_key
  ) RETURNING id INTO v_order_id;

  v_txn_ref := 'esim_' || v_order_id::text;

  PERFORM esim_private.reserve_order(v_order_id);

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'retail_price_usd', v_retail_price,
    'total_amount_usd', v_total_cost,
    'status', 'pending'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.snapshot_esim_catalogue_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.operation_kind='fixed_recharge' THEN RETURN NEW; END IF;
  SELECT jsonb_build_object('provider',c.provider,'bundle_name',c.bundle_name,
    'catalogue_details',c.catalogue_details,'countries',c.countries,
    'data_amount_mb',c.data_amount_mb,'duration_days',c.duration_days,
    'is_unlimited',c.is_unlimited,'retail_price_usd',NEW.retail_price_usd,
    'catalogue_observed_at',c.updated_at)
  INTO NEW.catalogue_snapshot FROM public.esim_offers_cache c
  WHERE c.provider=NEW.provider AND c.bundle_name=NEW.bundle_name;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION esim_private.emit_alert(p_profile_id uuid, p_order_id uuid, p_cycle_id uuid, p_event_type text, p_threshold integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE recharge_profile uuid; uid uuid; key text; cat text; title text; body text; target jsonb; n uuid; allowed boolean; decision text;
BEGIN
 PERFORM esim_private.require_service();
 IF p_profile_id IS NOT NULL THEN
  SELECT user_id INTO STRICT uid FROM public.user_esims WHERE id=p_profile_id;
  key:='esim:'||p_profile_id||':'||CASE WHEN p_event_type IN('esim_ready','esim_activated') THEN 'profile' ELSE p_cycle_id::text END||':'||p_event_type||':'||p_threshold;
  target:=jsonb_build_object('route','/esim/profiles/:id','id',p_profile_id);
 ELSE
  SELECT user_id INTO STRICT uid FROM public.esim_orders WHERE id=p_order_id AND provider='esimaccess';
  key:='esim:order:'||p_order_id||':'||p_event_type;
  SELECT recharge_profile_id INTO recharge_profile FROM public.esim_orders WHERE id=p_order_id;
  target:=CASE WHEN recharge_profile IS NULL THEN jsonb_build_object('route','/esim/orders/:id','id',p_order_id) ELSE jsonb_build_object('route','/esim/profiles/:id','id',recharge_profile) END;
 END IF;
 cat:=CASE WHEN p_event_type='esim_low_data' THEN 'esim_low_data' ELSE 'esim_updates' END;
 SELECT coalesce((SELECT is_enabled FROM public.alert_settings WHERE user_id=uid AND category=cat),true) INTO allowed;
 decision:=CASE WHEN allowed THEN 'queued' ELSE 'opted_out' END;
 INSERT INTO esim_private.alert_events(event_key,profile_id,order_id,cycle_id,event_type,threshold,decision)
 VALUES(key,p_profile_id,p_order_id,p_cycle_id,p_event_type,p_threshold,decision) ON CONFLICT DO NOTHING;
 IF NOT FOUND OR NOT allowed THEN RETURN false; END IF;
 title:=CASE p_event_type WHEN 'esim_ready' THEN 'Your eSIM is ready to install'
 WHEN 'esim_activated' THEN 'Your eSIM is active' WHEN 'esim_low_data' THEN 'Your eSIM data is running low'
 WHEN 'esim_near_expiry' THEN 'Your eSIM validity is ending soon' WHEN 'esim_expired' THEN 'Your eSIM has expired'
 WHEN 'esim_order_completed' THEN CASE WHEN recharge_profile IS NOT NULL THEN 'Your eSIM recharge is complete' ELSE 'Your eSIM order is ready' END ELSE 'Your eSIM order needs support' END;
 body:=CASE p_event_type WHEN 'esim_ready' THEN 'Open your eSIM securely in KeepSIMs to view installation details.'
 WHEN 'esim_activated' THEN 'Open your eSIM to review its latest usage and confirmed validity.'
 WHEN 'esim_low_data' THEN 'Your latest reported allowance is at or below '||p_threshold||'%. Open your eSIM to review usage. Open your eSIM to review compatible recharge options.'
 WHEN 'esim_near_expiry' THEN 'Open your eSIM to check its confirmed expiry in your local time. Open your eSIM to review compatible recharge options.'
 WHEN 'esim_expired' THEN 'The latest provider check confirms expiry. Open your eSIM to review its status.'
 WHEN 'esim_order_completed' THEN 'Open My eSIMs in KeepSIMs to view your profiles and installation details.'
 ELSE 'Your order needs a support review. Open My eSIMs to review the order; this alert does not confirm a refund.' END;
 INSERT INTO public.notifications(user_id,category,title,body,event_type,schema_version,source_event_key,action_url,target,
  occurred_at,expires_at,template_version,template_data,delivered_via)
 VALUES(uid,cat,title,body,p_event_type,2,key,replace(target->>'route',':id',target->>'id'),target,
  now(),now()+interval '24 hours',1,jsonb_build_object('profile_id',p_profile_id,'cycle_id',p_cycle_id,'threshold',p_threshold),ARRAY[]::text[])
 RETURNING id INTO n;
 UPDATE esim_private.alert_events SET notification_id=n WHERE event_key=key;
 RETURN true;
END $function$;

CREATE OR REPLACE FUNCTION public.request_esim_purchase(p_offer_id text,p_quantity integer DEFAULT 1,p_device_id text DEFAULT NULL)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('success',false,'code','UPDATE_REQUIRED','error','Reopen checkout in the updated app to review this purchase.');
$$;

CREATE OR REPLACE FUNCTION public.service_esim_save_issuance(p_order_id uuid, p_lease uuid, p_provider_order_ref text, p_profiles jsonb, p_transaction_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r esim_private.order_runs%ROWTYPE; o public.esim_orders%ROWTYPE; item jsonb;
 existing public.user_esims%ROWTYPE; new_id uuid; count_profiles integer; conflict boolean:=false;
BEGIN
 PERFORM esim_private.require_service();
 PERFORM 1 FROM public.wallets WHERE user_id=(SELECT user_id FROM public.esim_orders WHERE id=p_order_id) FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 IF r.state='completed' THEN RETURN jsonb_build_object('completed',true); END IF;
 IF p_lease IS NULL OR r.lease IS NULL OR r.lease_until IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until<now() THEN RAISE EXCEPTION 'Expired order lease'; END IF;
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id FOR UPDATE;
 IF o.operation_kind<>'purchase' OR o.user_id IS NULL OR o.provider<>'esimaccess' OR o.status NOT IN('pending','processing') THEN RAISE EXCEPTION 'Order is not eligible'; END IF;
 IF nullif(p_provider_order_ref,'') IS NULL OR
  (r.provider_order_ref IS NOT NULL AND r.provider_order_ref<>p_provider_order_ref) OR
  (r.provider_order_ref IS NULL AND p_transaction_id IS DISTINCT FROM r.submission_ref) THEN RAISE EXCEPTION 'Unproven order binding'; END IF;
 IF p_profiles IS NULL OR jsonb_typeof(p_profiles)<>'array' OR jsonb_array_length(p_profiles)>o.quantity OR octet_length(p_profiles::text)>65536 THEN RAISE EXCEPTION 'Invalid allocation batch'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_profiles) LOOP
  IF item->>'provider_order_ref' IS DISTINCT FROM p_provider_order_ref OR item->>'issuance_proven' IS DISTINCT FROM 'true'
   OR coalesce(item->>'supplier_profile_ref','')='' OR coalesce(item->>'iccid','')!~'^[0-9]{15,22}$'
   OR coalesce(item->>'lpa_string','')!~'^LPA:1\$[^$[:space:]]+\$[^$[:space:]]+'
  OR coalesce(item->>'smdp_address','')='' OR coalesce(item->>'matching_id','')=''
  OR split_part(item->>'lpa_string','$',2) IS DISTINCT FROM item->>'smdp_address'
  OR split_part(item->>'lpa_string','$',3) IS DISTINCT FROM item->>'matching_id'
  OR item->>'profile_state' IN('cancelled','revoked','expired') THEN CONTINUE; END IF;
  SELECT * INTO existing FROM public.user_esims WHERE provider='esimaccess' AND supplier_account_id=r.account_id
   AND supplier_profile_ref=item->>'supplier_profile_ref' FOR UPDATE;
  IF FOUND THEN
   IF existing.user_id IS DISTINCT FROM o.user_id OR existing.order_id<>o.id OR existing.iccid<>item->>'iccid'
    OR existing.lpa_string<>item->>'lpa_string' THEN conflict:=true; END IF;
   CONTINUE;
  END IF;
  BEGIN
   INSERT INTO public.user_esims(user_id,order_id,provider,bundle_name,iccid,smdp_address,matching_id,lpa_string,
     status,purchased_at,data_total_mb,data_remaining_mb,supplier_account_id,supplier_profile_ref,profile_state,
     installation_state,bundle_state,provider_state,activation_trigger,confirmed_expires_at,plan_details,
     data_total_bytes,data_used_bytes,data_remaining_bytes,last_usage_check,last_observation_at)
   VALUES(o.user_id,o.id,o.provider,o.bundle_name,item->>'iccid',item->>'smdp_address',item->>'matching_id',item->>'lpa_string',
    'active',o.created_at,coalesce(floor((item->>'data_total_bytes')::numeric/1048576)::bigint,0),
    coalesce(floor((item->>'data_remaining_bytes')::numeric/1048576)::bigint,0),r.account_id,item->>'supplier_profile_ref',coalesce(item->>'profile_state','unknown'),
    coalesce(item->>'installation_state','unknown'),coalesce(item->>'bundle_state','unknown'),coalesce(item->'provider_state','{}'),
    coalesce(item->>'activation_trigger','unknown'),(item->>'confirmed_expires_at')::timestamptz,o.catalogue_snapshot->'catalogue_details',
    (item->>'data_total_bytes')::bigint,(item->>'data_used_bytes')::bigint,(item->>'data_remaining_bytes')::bigint,
    CASE WHEN item->>'data_remaining_bytes' IS NOT NULL THEN now() END,clock_timestamp()) RETURNING id INTO new_id;
   INSERT INTO esim_private.profile_work(profile_id) VALUES(new_id);
  EXCEPTION WHEN unique_violation THEN conflict:=true;
  END;
 END LOOP;
 SELECT count(*) INTO count_profiles FROM public.user_esims WHERE order_id=o.id AND user_id=o.user_id
  AND provider=o.provider AND supplier_account_id=r.account_id AND supplier_profile_ref IS NOT NULL;
 IF count_profiles=o.quantity AND NOT conflict THEN
  UPDATE esim_private.order_runs SET receipt=jsonb_build_object('outcome','success','source','verified_issuance',
   'transaction_id',submission_ref,'provider_order_ref',p_provider_order_ref,'profiles',count_profiles),receipt_at=now() WHERE order_id=o.id;
  PERFORM esim_private.settle_order(o.id,true);
 END IF;
 UPDATE esim_private.order_runs SET provider_order_ref=p_provider_order_ref,state=CASE WHEN conflict THEN 'support_required'
  WHEN count_profiles=o.quantity THEN 'completed' ELSE 'reconciling' END,
  next_check_at=CASE WHEN count_profiles=o.quantity OR conflict THEN NULL ELSE now()+interval '1 minute' END,
  lease=NULL,lease_until=NULL,error_code=CASE WHEN conflict THEN 'IDENTITY_CONFLICT' WHEN count_profiles<o.quantity THEN 'PARTIAL_ISSUANCE' END,updated_at=now()
 WHERE order_id=o.id;
 UPDATE public.esim_orders SET status=CASE WHEN count_profiles=o.quantity AND NOT conflict THEN 'completed' ELSE 'processing' END,
  delivery_state=CASE WHEN conflict THEN 'support_required' WHEN count_profiles=o.quantity THEN 'completed' ELSE 'reconciling' END,
  provider_order_ref=p_provider_order_ref,updated_at=now() WHERE id=o.id;
 RETURN jsonb_build_object('completed',count_profiles=o.quantity AND NOT conflict,'profiles',count_profiles,'conflict',conflict);
END $function$;

UPDATE esim_private.order_runs r SET payer_id=o.user_id FROM public.esim_orders o WHERE o.id=r.order_id;
WITH proof AS(SELECT o.id,min(t.id::text)::uuid tx FROM public.esim_orders o JOIN public.wallet_transactions t
 ON t.reference_id='esim_'||o.id::text AND t.user_id=o.user_id AND t.type='esim_purchase_debit' AND t.status='completed'
 AND t.amount>0 AND t.amount=t.balance_before-t.balance_after GROUP BY o.id HAVING count(*)=1)
UPDATE esim_private.order_runs r SET finance_kind='legacy_debit',debit_tx_id=p.tx FROM proof p WHERE r.order_id=p.id AND r.hold_id IS NULL;

DO $$ BEGIN IF md5(pg_get_viewdef('public.wallet_reconciliation'::regclass,true))<>'bf00f58dc537ee6ee6bf7967c608f39f' THEN RAISE EXCEPTION 'Wallet reconciliation source drift'; END IF; END $$;

CREATE OR REPLACE VIEW public.wallet_reconciliation AS
 SELECT w.id AS wallet_id,
    w.user_id,
    w.balance,
    COALESCE(sum(
        CASE
            WHEN t.type = ANY (ARRAY['deposit'::text, 'refund'::text, 'esim_purchase_refund'::text, 'esim_recharge_refund'::text, 'referral_credit'::text, 'auto_fund'::text, 'gift_received'::text, 'admin_credit'::text]) THEN t.amount
            WHEN t.type = ANY (ARRAY['topup_debit'::text, 'welcome_home_debit'::text, 'plan_fee_debit'::text, 'esim_purchase_debit'::text, 'esim_recharge_debit'::text, 'call_debit'::text, 'voucher_purchase_debit'::text, 'gift_sent'::text, 'refund_payout'::text, 'admin_debit'::text]) THEN - t.amount
            ELSE 0.00
        END), 0.00) AS ledger_sum,
    w.balance - COALESCE(sum(
        CASE
            WHEN t.type = ANY (ARRAY['deposit'::text, 'refund'::text, 'esim_purchase_refund'::text, 'esim_recharge_refund'::text, 'referral_credit'::text, 'auto_fund'::text, 'gift_received'::text, 'admin_credit'::text]) THEN t.amount
            WHEN t.type = ANY (ARRAY['topup_debit'::text, 'welcome_home_debit'::text, 'plan_fee_debit'::text, 'esim_purchase_debit'::text, 'esim_recharge_debit'::text, 'call_debit'::text, 'voucher_purchase_debit'::text, 'gift_sent'::text, 'refund_payout'::text, 'admin_debit'::text]) THEN - t.amount
            ELSE 0.00
        END), 0.00) AS drift
   FROM wallets w
     LEFT JOIN wallet_transactions t ON t.wallet_id = w.id
  GROUP BY w.id, w.user_id, w.balance;

CREATE OR REPLACE VIEW public.customer_esim_orders AS
 SELECT id,
    user_id,
    provider,
    bundle_name,
    quantity,
    retail_price_usd,
    status,
    created_at,
    updated_at,
    total_amount_usd,
        CASE
            WHEN (status = 'failed'::text) THEN 'eSIM order could not be completed.'::text
            ELSE NULL::text
        END AS error_message,
    delivery_state
   FROM esim_orders WHERE operation_kind='purchase';

CREATE OR REPLACE FUNCTION public.prune_esim_topup_discovery() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM esim_private.require_service();
 DELETE FROM esim_private.recharge_quotes q WHERE expires_at<now()-interval '30 days' AND NOT EXISTS(SELECT 1 FROM public.esim_orders WHERE recharge_quote_id=q.id);
 DELETE FROM esim_private.topup_cache WHERE requested_at<now()-interval '1 day'; END $$;

DO $$DECLARE r record; BEGIN
 FOR r IN SELECT p.oid::regprocedure sig,p.proname FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND
  p.proname IN('request_esim_purchase_v2','accept_esim_topup','get_esim_operation_history','admin_esim_operation_timeline','service_esim_adopt_purchase_reference','service_esim_record_topup_receipt','service_esim_settle_topup','service_esim_record_rejection','service_esim_fail_before_submit') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',r.sig);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',r.sig);
  IF r.proname IN('request_esim_purchase_v2','accept_esim_topup','get_esim_operation_history','admin_esim_operation_timeline') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.sig); END IF;
 END LOOP;
 FOR r IN SELECT p.oid::regprocedure sig FROM pg_proc p WHERE p.pronamespace='esim_private'::regnamespace AND p.proname IN(
 'recharge_can_accept','require_live_owner','require_money_session','reserve_order','guard_operation_hold','guard_reserved_wallet','settle_order','topup_refusal_base') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',r.sig);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',r.sig);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';
COMMIT;
